-	p->sched_remote_wakeup = !!(wake_flags & WF_MIGRATED);
+	p->sched_remote_wakeup_flags = wake_flags &
+		(WF_TTWU | WF_SYNC | WF_MIGRATED | WF_RQ_SELECTED);
 
 	WRITE_ONCE(rq->ttwu_pending, 1);
